<?php
declare(strict_types=1);
require __DIR__ . '/../lib/bootstrap.php';
require __DIR__ . '/../includes/seo.php';
$slug=trim((string)($_GET['slug']??''));
$stmt=db()->prepare("SELECT p.*,c.name AS category_name,c.slug AS category_slug FROM products p LEFT JOIN categories c ON c.id=p.category_id AND c.active=1 WHERE p.slug=? AND p.active=1 LIMIT 1");
$stmt->execute([$slug]); $product=$stmt->fetch();
if(!$product){http_response_code(404);$title='Producto no encontrado | '.BUSINESS_NAME;$description='El producto solicitado no está disponible.';}else{$title=trim((string)($product['seo_title']??''))?:$product['name'].' | '.BUSINESS_NAME;$description=trim((string)($product['seo_description']??''))?:($product['short_description']?:'Consulta por '.$product['name'].' en '.BUSINESS_NAME.'. Despacho sujeto a coordinación en la zona lacustre.');}
$image=null;$images=[];
if($product){$q=db()->prepare('SELECT path,alt_text FROM product_images WHERE product_id=? ORDER BY is_cover DESC,sort_order,id');$q->execute([$product['id']]);$images=$q->fetchAll();$image=$images[0]['path']??null;}
?><!doctype html><html lang="es-CL"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0825a7"><?php seo_head(['title'=>$title,'description'=>$description,'path'=>'/producto/'.rawurlencode($slug).'/','image'=>$image?BUSINESS_DOMAIN.'/'.$image:null,'type'=>'product','noindex'=>$product&&!($product['seo_indexable']??1)]);?><link rel="stylesheet" href="../styles.css"><?php seo_jsonld(seo_business_schema());<?php if($product):$schema=['@context'=>'https://schema.org','@type'=>'Product','name'=>$product['name'],'description'=>$product['description']?:$description,'sku'=>$product['sku']?:null,'brand'=>$product['brand']?['@type'=>'Brand','name'=>$product['brand']]:null,'image'=>array_map(fn($i)=>BUSINESS_DOMAIN.'/'.$i['path'],$images),'url'=>BUSINESS_DOMAIN.'/producto/'.rawurlencode($slug).'/'];if($product['price']!==null)$schema['offers']=['@type'=>'Offer','priceCurrency'=>'CLP','price'=>(string)$product['price'],'availability'=>'https://schema.org/'.($product['stock_mode']==='track'&&$product['stock']<1?'OutOfStock':'InStock'),'url'=>$schema['url']];seo_jsonld(array_filter($schema,fn($v)=>$v!==null));endif;?></head><body><header class="site-header"><a class="brand" href="../index.html"><span>Ferretería<br><strong>El Volcán</strong></span></a><nav><a href="../index.html">Inicio</a><a href="../catalogo.html">Catálogo</a><a href="../ofertas.html">Ofertas</a></nav></header><main class="catalog-section"><?php if(!$product):?><h1>Producto no encontrado</h1><p>Revisa el catálogo completo.</p><a class="button primary" href="../catalogo.html">Ir al catálogo</a><?php else:?><p class="eyebrow dark"><?=seo_escape($product['category_name']??'Ferretería')?></p><h1><?=seo_escape($product['name'])?></h1><?php if($images):?><div class="product-grid"><?php foreach($images as $i):?><figure><img src="../<?=seo_escape($i['path'])?>" alt="<?=seo_escape($i['alt_text']?:$product['name'])?>" loading="lazy"><figcaption><?=seo_escape($i['alt_text']?:$product['name'])?></figcaption></figure><?php endforeach;?></div><?php endif;?><p><?=nl2br(seo_escape($product['description']?:$product['short_description']?:''))?></p><?php if($product['sku']):?><p>SKU: <?=seo_escape($product['sku'])?></p><?php endif;?><?php if($product['brand']):?><p>Marca: <?=seo_escape($product['brand'])?></p><?php endif;?><p>Precio y disponibilidad: consultar.</p><a class="button whatsapp" target="_blank" rel="noopener" href="https://wa.me/<?=BUSINESS_WHATSAPP?>?text=<?=rawurlencode('Hola, quisiera cotizar '.$product['name'].' (SKU '.($product['sku']?:'sin SKU').').') ?>">Cotizar por WhatsApp</a><?php if($product['category_slug']):?><p><a href="../categoria/<?=rawurlencode($product['category_slug'])?>/">Ver categoría <?=seo_escape($product['category_name'])?></a></p><?php endif;?><?php endif;?></main><footer><p><?=BUSINESS_NAME?> · <?=BUSINESS_ADDRESS?></p><p><?=BUSINESS_HOURS?></p><a href="<?=BUSINESS_FACEBOOK?>">Facebook</a> · <a href="<?=BUSINESS_INSTAGRAM?>">Instagram</a> · <a href="<?=BUSINESS_MAPS?>">Cómo llegar</a></footer></body></html>
